import{_ as e,o as d,c as r,ai as o}from"./chunks/framework.CAnUr3M0.js";const u=JSON.parse('{"title":"浏览器进程与渲染","description":"","frontmatter":{},"headers":[],"relativePath":"browser/rendering.md","filePath":"browser/rendering.md"}'),a={name:"browser/rendering.md"};function l(n,t,i,s,c,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="浏览器进程与渲染" tabindex="-1">浏览器进程与渲染 <a class="header-anchor" href="#浏览器进程与渲染" aria-label="Permalink to &quot;浏览器进程与渲染&quot;">​</a></h1><blockquote><p>多进程架构 · 单线程原因 · URL→页面 · CRP · 资源加载 · defer/async · 复合层 · 硬件加速</p></blockquote><hr><h2 id="一、多进程架构-chrome-2008-起" tabindex="-1">一、多进程架构（Chrome 2008 起） <a class="header-anchor" href="#一、多进程架构-chrome-2008-起" aria-label="Permalink to &quot;一、多进程架构（Chrome 2008 起）&quot;">​</a></h2><ul><li>打开一个 Tab 至少 4 个进程：浏览器主进程、GPU 进程、网络进程、渲染进程</li></ul><table tabindex="0"><thead><tr><th>进程</th><th>职责</th></tr></thead><tbody><tr><td>浏览器进程（Browser Process）</td><td>界面显示、用户交互、子进程管理、存储</td></tr><tr><td>渲染进程（Renderer Process）</td><td>HTML/CSS/JS → 可交互网页，包含 Blink + V8，运行在沙箱</td></tr><tr><td>GPU 进程</td><td>3D CSS 效果、网页和 UI 界面的 GPU 绘制</td></tr><tr><td>网络进程（Network Process）</td><td>页面网络资源加载</td></tr><tr><td>插件进程</td><td>每种插件类型一个进程，隔离崩溃影响</td></tr></tbody></table><p><strong>多进程优势</strong>：进程隔离（单页崩溃不影响全局）、JS 阻塞只影响当前页、关闭页面整个渲染进程被回收、沙箱机制限制系统权限</p><p><strong>多进程缺点</strong>：更高内存占用，每个进程有公共基础结构副本</p><p>渲染进程内部线程：主线程、GUI 渲染线程、事件触发线程、定时器线程、HTTP 请求线程</p><h3 id="为什么-js-是单线程" tabindex="-1">为什么 JS 是单线程？ <a class="header-anchor" href="#为什么-js-是单线程" aria-label="Permalink to &quot;为什么 JS 是单线程？&quot;">​</a></h3><ul><li>JS 为处理用户交互、操作 DOM 树和 CSS 样式树而诞生</li><li>多线程同时操作同一 DOM 节点（一个修改、一个删除），浏览器无法裁决</li><li>为避免引入锁机制的复杂性，JS 选择了单线程</li><li><strong>推论</strong>：GUI 渲染线程与 JS 引擎线程互斥 → JS 执行时间过长会导致页面渲染不连贯</li></ul><hr><h2 id="二、从输入-url-到页面展示" tabindex="-1">二、从输入 URL 到页面展示 <a class="header-anchor" href="#二、从输入-url-到页面展示" aria-label="Permalink to &quot;二、从输入 URL 到页面展示&quot;">​</a></h2><ol><li><strong>URL 解析</strong>：判断是 URL 还是搜索关键词</li><li><strong>DNS 查询</strong>：域名 → IP 地址（浏览器缓存 → 系统 hosts → 本地 DNS → 根服务器递归查询）</li><li><strong>TCP 连接</strong>：三次握手（SYN → SYN-ACK → ACK）</li><li><strong>TLS 协商</strong>（仅 HTTPS）：协商加密算法、验证证书、建立安全连接</li><li><strong>HTTP 请求</strong>：发送请求到服务器</li><li><strong>服务器响应</strong>：处理请求，返回 HTTP 响应（<strong>TTFB 首字节时间</strong>）</li><li><strong>页面渲染</strong>： <ul><li>解析 HTML 构建 DOM 树（Bytes → characters → tokens → nodes → DOM）</li><li>解析 CSS 生成 CSSOM 规则树</li><li>合并 DOM + CSSOM 生成 render 树（排除 <code>display:none</code>、<code>head</code> 等不可见节点）</li><li>布局（Layout/reflow）：计算元素尺寸位置坐标</li><li>绘制（paint）：像素信息</li><li>合成（composite）：GPU 合成显示</li></ul></li></ol><hr><h2 id="三、关键渲染路径-crp-优化" tabindex="-1">三、关键渲染路径（CRP）优化 <a class="header-anchor" href="#三、关键渲染路径-crp-优化" aria-label="Permalink to &quot;三、关键渲染路径（CRP）优化&quot;">​</a></h2><p><strong>优化策略</strong>：</p><ol><li><strong>优化 DOM</strong>：删除不必要代码/注释/空格，GZIP 压缩</li><li><strong>优化 CSSOM</strong>：减少关键 CSS 体积，非关键 CSS 标记为 <code>media</code> 查询</li><li><strong>优化 JS</strong>：消除阻塞渲染的 JS（<code>async</code>/<code>defer</code>），将非关键 JS 延迟执行</li><li><strong>优化关键字节</strong>：缩小压缩文件减少下载时间</li></ol><h3 id="资源加载对渲染的影响" tabindex="-1">资源加载对渲染的影响 <a class="header-anchor" href="#资源加载对渲染的影响" aria-label="Permalink to &quot;资源加载对渲染的影响&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资源</th><th>阻塞 DOM 解析</th><th>阻塞渲染</th><th>备注</th></tr></thead><tbody><tr><td>CSS</td><td>不阻塞</td><td><strong>阻塞</strong>（等 CSSOM 才构建 render 树）</td><td>media query 声明的 CSS 不阻塞</td></tr><tr><td>JS（普通）</td><td><strong>阻塞</strong></td><td>阻塞</td><td>必须下载执行完才继续解析</td></tr><tr><td>JS（async）</td><td>不阻塞</td><td>无序</td><td>加载完立即执行</td></tr><tr><td>JS（defer）</td><td>不阻塞</td><td>按序</td><td>DOM 解析完毕后按顺序执行</td></tr><tr><td>img</td><td>不阻塞</td><td>不阻塞</td><td>异步下载，下载完替换位置</td></tr></tbody></table><h3 id="defer-vs-async-对比" tabindex="-1">defer vs async 对比 <a class="header-anchor" href="#defer-vs-async-对比" aria-label="Permalink to &quot;defer vs async 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>defer</th><th>async</th></tr></thead><tbody><tr><td>执行顺序</td><td>按文档中的顺序</td><td>加载优先（谁先下完谁先执行）</td></tr><tr><td>DOMContentLoaded</td><td>DOM 解析完毕后、DOMContentLoaded 之前</td><td>不相关，可能在之前或之后</td></tr><tr><td>适用场景</td><td>需要完整 DOM 或依赖执行顺序的脚本</td><td>独立的第三方脚本（统计、广告）</td></tr></tbody></table><h3 id="link-标签资源预加载" tabindex="-1"><code>&lt;link&gt;</code> 标签资源预加载 <a class="header-anchor" href="#link-标签资源预加载" aria-label="Permalink to &quot;`&lt;link&gt;` 标签资源预加载&quot;">​</a></h3><ul><li><strong><code>&lt;link rel=&quot;preload&quot;&gt;</code></strong>：告诉浏览器尽早请求当前页面必需的关键资源，不阻塞 <code>onload</code>；必须设置 <code>as</code> 属性</li><li><strong><code>&lt;link rel=&quot;prefetch&quot;&gt;</code></strong>：利用浏览器空闲时间静默下载后续页面可能需要的资源，存入缓存</li></ul><h3 id="document-readystate-状态" tabindex="-1">document.readyState 状态 <a class="header-anchor" href="#document-readystate-状态" aria-label="Permalink to &quot;document.readyState 状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>对应事件</th></tr></thead><tbody><tr><td><code>loading</code></td><td>正在解析 HTML，构建 DOM 树</td><td>—</td></tr><tr><td><code>interactive</code></td><td>DOM 解析完毕，defer 脚本按顺序执行</td><td><code>DOMContentLoaded</code></td></tr><tr><td><code>complete</code></td><td>所有资源（含图片、异步脚本）加载完毕</td><td><code>load</code></td></tr></tbody></table><hr><h2 id="四、复合层与硬件加速" tabindex="-1">四、复合层与硬件加速 <a class="header-anchor" href="#四、复合层与硬件加速" aria-label="Permalink to &quot;四、复合层与硬件加速&quot;">​</a></h2><ul><li>默认只有一个<strong>复合图层</strong>，所有 DOM 节点都在其下</li><li>开启<strong>硬件加速</strong>（<code>transform: translate3d()</code>、<code>will-change</code>）可将节点提升为独立复合图层</li><li>复合图层间绘制互不干扰，由 GPU 直接控制</li><li><strong>仅触发合成的 CSS 属性</strong>（不回流不重绘）：只有 <code>transform</code> 和 <code>opacity</code></li></ul><p><strong>内存占用</strong>：每个复合层需缓存图像数据（宽 × 高 × 4 字节），不可滥用</p><p><strong>动画优化技巧</strong>：</p><ol><li>避免隐式合成：保持动画对象 z-index 尽可能高</li><li>动画中只使用 <code>transform</code> 和 <code>opacity</code></li><li><code>will-change</code> 慎用，滥用会大幅增加内存</li></ol><blockquote><p>性能优化完整内容详见 <a href="./../performance/">性能优化专题</a></p></blockquote><hr><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./html.html">HTML 基础</a> — 标签、语义化、本地存储</li><li><a href="./network.html">网络协议与缓存</a> — HTTP/TCP、缓存策略</li><li><a href="./../javascript/engine.html">JS 引擎与执行上下文</a> — V8 引擎执行流程</li></ul>',36)])])}const S=e(a,[["render",l]]);export{u as __pageData,S as default};
